#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.."&&pwd -P)";WORKSPACE="$(realpath -e -- "${WORKSPACE_ROOT:-/guisongxia01/pangchao/wangyihan}")";PRIMARY="$(realpath -e -- "${PRIMARY_REPO:-$WORKSPACE/Chang-Agent}")";OUTROOT="$(realpath -e -- "$PRIMARY/outputs")";PROFILE="${EVALUATION_PROFILE:-e2e3}";NODE="${NODE:?NODE required}";MODEL_PATH="$(realpath -e -- "${MODEL_PATH:?MODEL_PATH required}")";COMMIT="$(git -C "$ROOT" rev-parse HEAD)";WORKER="$ROOT/tools/run_qwen3vl_v121_post_sft_e2e.slurm"
if [[ "$PROFILE" == e2e3 ]];then DEFAULT="$OUTROOT/CA_0801(10)-qwen3vl-v121-post-sft-e2e3-v1";NAME=CA0801V121E2E3;else DEFAULT="$OUTROOT/CA_0801(11)-qwen3vl-v121-post-sft-e2e5-v1";NAME=CA0801V121E2E5;fi;OUTPUT="$(realpath -m -- "${OUTPUT:-$DEFAULT}")"
[[ "$OUTPUT" == "$OUTROOT/"* && ! -e "$OUTPUT" ]]||exit 2;[[ -f "$(dirname "$MODEL_PATH")/.training_complete" ]]||{ echo "training incomplete" >&2;exit 2; };[[ -z "$(git -C "$ROOT" status --porcelain --untracked-files=all)" ]]||exit 2
scontrol ping|grep -q UP||exit 3;ACTIVE="$(squeue -h -u guisongxia --name="$NAME" -o '%i %T')";[[ -z "$ACTIVE" ]]||exit 2;INFO="$(scontrol show node "$NODE")";grep -Eq 'State=[^ ]*(DOWN|DRAIN|FAIL|MAINT)'<<<"$INFO"&&exit 2
mkdir "$OUTPUT";mkdir "$OUTPUT/logs";JOB="$(sbatch --parsable --job-name="$NAME" --partition=gre --nodelist="$NODE" --gres=gpu:1 --cpus-per-task=4 --mem=48G --time=03:00:00 --output="$OUTPUT/logs/slurm-%j.out" --error="$OUTPUT/logs/slurm-%j.err" --export="ALL,REPO_ROOT=$ROOT,WORKSPACE_ROOT=$WORKSPACE,MODEL_PATH=$MODEL_PATH,EXPECTED_COMMIT=$COMMIT,EVALUATION_PROFILE=$PROFILE" "$WORKER" "$OUTPUT")";JOB="${JOB%%;*}"
printf 'job_id=%s\nprofile=%s\nnode=%s\nmodel=%s\ncommit=%s\noutput=%s\n' "$JOB" "$PROFILE" "$NODE" "$MODEL_PATH" "$COMMIT" "$OUTPUT" >"$OUTPUT/submission.txt";printf 'job=%s\noutput=%s\n' "$JOB" "$OUTPUT"
